test('lineVat with bulk discount (qty >= 10)', () => {
  // qty=10, unitPrice=1000, no discount, vatRate=21
  // baseTotal: 10000, no line discount, bulk discount: 10000 * 2.5% = 250
  // amount after discount: 10000 - 250 = 9750
  // vat: 9750 * 21% = 2047.5 = 2048
  const vat = lineVat({ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 });
  assert.equal(vat, 2048);
});

test('lineVat without bulk discount (qty < 10)', () => {
  // qty=9, unitPrice=1000, no discount, vatRate=21
  // baseTotal: 9000, no bulk discount
  // vat: 9000 * 21% = 1890
  const vat = lineVat({ qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 21 });
  assert.equal(vat, 1890);
});

test('lineVat bulk discount after line discount', () => {
  // qty=10, unitPrice=1000, discountPercent=5, vatRate=21
  // baseTotal: 10000
