test('invoiceTotals with mixed tier discounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 }, // 85000, 5% discount = 4250, after discount 80750, VAT 21% = 16957.50 = 16958
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }, // 47500, explicit 0% = 0, VAT 21% = 9975
    ],
  });

  const totals = invoiceTotals(invoiceResult.value);
  // subtotal: 85000 + 47500 = 132500
  // discount: 4250 + 0 = 4250
  // vat: 16958 + 9975 = 26933
  // total: 132500 - 4250 + 26933 = 155183
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 4250);
  assert.equal(totals.vat, 26933);
  assert.equal(totals.total, 155183);
});

test('invoiceTotals calculates VAT for single line', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 100000
  // discount: 0
  // vat: 100000 * 21 / 100 = 21000
  // total: 100000 - 0 + 21000 = 121000
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 21000);
  assert.equal(totals.total, 121000);
});

