import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineVat, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';
import { normalizeId, getCustomer } from '../src/customers.js';

test('normalizeId trims whitespace', () => {
  assert.equal(normalizeId(' C-001 '), 'C-001');
  assert.equal(normalizeId('  C-003  '), 'C-003');
  assert.equal(normalizeId('C-005'), 'C-005');
});

test('normalizeId converts to uppercase', () => {
  assert.equal(normalizeId('c-001'), 'C-001');
  assert.equal(normalizeId('c-003'), 'C-003');
  assert.equal(normalizeId('C-005'), 'C-005');
});

test('normalizeId handles mixed case and whitespace', () => {
  assert.equal(normalizeId(' c-007 '), 'C-007');
  assert.equal(normalizeId('  C-002  '), 'C-002');
  assert.equal(normalizeId('c-010'), 'C-010');
});

test('getCustomer accepts normalized and non-normalized IDs', () => {
  const result1 = getCustomer('C-001');
  assert.equal(result1.ok, true);
  assert.equal(result1.value.id, 'C-001');

  const result2 = getCustomer('c-001');
  assert.equal(result2.ok, true);
  assert.equal(result2.value.id, 'C-001');

  const result3 = getCustomer(' c-001 ');
  assert.equal(result3.ok, true);
  assert.equal(result3.value.id, 'C-001');
});

test('createInvoice normalizes and stores customer ID', () => {
  const result = createInvoice({
    customerId: ' c-001 ',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice accepts lowercase customer ID', () => {
  const result = createInvoice({
    customerId: 'c-003',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
});

test('createInvoice accepts mixed case with spaces', () => {
  const result = createInvoice({
    customerId: '  c-002  ',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-002');
});

test('createInvoice creates a draft invoice with enriched lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-01-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);

  const line = result.value.lines[0];
  assert.equal(line.sku, 'DES-HOUR');
  assert.equal(line.name, 'Design work (hour)');
  assert.equal(line.qty, 10);
  assert.equal(line.unitPrice, 8500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice accepts multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-02-20',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 8 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
});

test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for malformed date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '15/01/2024',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-1-15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-35',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports DATE_INVALID for impossible dates', () => {
  // February 30th doesn't exist
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  // April only has 30 days
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-04-31',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice accepts valid dates including leap year dates', () => {
  // 2024 is a leap year, Feb 29 exists
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-29',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);

  // 2023 is not a leap year, Feb 28 exists
  const result2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-02-28',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result2.ok, true);
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports NO_LINES when lines is not an array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: undefined,
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports QTY_INVALID for zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for non-integer quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports UNKNOWN_SKU for unknown product', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'FAKE-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice returns copies, not references', () => {
  const inputLines = [{ sku: 'DES-HOUR', qty: 1 }];
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: inputLines,
  });

  // Mutate the returned line
  result.value.lines[0].qty = 999;

  // Original should be unchanged
  assert.equal(inputLines[0].qty, 1);
});

test('createInvoice does not mutate input array', () => {
  const inputLines = [{ sku: 'DES-HOUR', qty: 1 }];
  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: inputLines,
  });

  // Input should be unchanged
  assert.equal(inputLines[0].qty, 1);
  assert.equal(Object.keys(inputLines[0]).length, 2);
});

test('createInvoice works with various VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'PRINT-A4', qty: 100 }, // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT (exempt)
      { sku: 'DES-HOUR', qty: 5 }, // 21% VAT
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 9);
  assert.equal(result.value.lines[1].vatRate, 0);
  assert.equal(result.value.lines[2].vatRate, 21);
});

test('lineTotal calculates qty × unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
});

test('lineTotal returns 0 for zero quantity', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 8500 }), 0);
});

test('lineTotal works with different unit prices', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 1 }), 5);
  assert.equal(lineTotal({ qty: 1, unitPrice: 1 }), 1);
  assert.equal(lineTotal({ qty: 1000, unitPrice: 10000 }), 10000000);
});

test('lineVat calculates VAT on line amount after discount', () => {
  // 100 * 1000 = 100000, no discount, bulk discount 2.5% = 2500, remaining 97500, 21% VAT = 20475
  const vat1 = lineVat({ qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 0 });
  assert.equal(vat1, 20475);

  // 100 * 1000 = 100000, 10% discount = 10000, bulk discount 2.5% = 2250, remaining 87750, 21% VAT = 18428
  const vat2 = lineVat({ qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 10 });
  assert.equal(vat2, 18428);

  // 100 * 1000 = 100000, no discount, bulk discount 2.5% = 2500, remaining 97500, 9% VAT = 8775
  const vat3 = lineVat({ qty: 100, unitPrice: 1000, vatRate: 9, discountPercent: 0 });
  assert.equal(vat3, 8775);

  // 100 * 1000 = 100000, no discount, 0% VAT = 0
  const vat4 = lineVat({ qty: 100, unitPrice: 1000, vatRate: 0, discountPercent: 0 });
  assert.equal(vat4, 0);
});

test('lineVat with tier discount', () => {
  // 100 * 1000 = 100000, 5% tier discount = 5000, remaining 95000, bulk discount 2.5% = 2375, final 92625, 21% VAT = 19451
  const vat = lineVat({ qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 5 });
  assert.equal(vat, 19451);
});

test('lineVat defaults discountPercent and vatRate to 0 if missing', () => {
  const vat1 = lineVat({ qty: 100, unitPrice: 1000 });
  assert.equal(vat1, 0);

  const vat2 = lineVat({ qty: 100, unitPrice: 1000, discountPercent: undefined });
  assert.equal(vat2, 0);
});

test('invoiceTotals sums line totals for single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  // qty >= 10 triggers bulk discount: 85000 * 2.5% = 2125
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 82875);
});

test('invoiceTotals sums line totals for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 0 }, // 85000, bulk discount: 2125
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 0 }, // 47500, no bulk discount
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 0 }, // 120000, no bulk discount
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 252500);
  assert.equal(totals.discount, 2125); // bulk discount on first line
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 250375);
});

test('invoiceTotals returns 0 for empty invoice', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals returns a new object', () => {
  const invoice = { lines: [{ qty: 5, unitPrice: 1000 }] };
  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);
  assert.notEqual(totals1, totals2);
  assert.deepEqual(totals1, totals2);
});

test('invoiceTotals with real invoice from createInvoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(invoiceResult.value);
  // C-001 is gold tier, so lines get 5% discount
  // DES-HOUR: 10 * 8500 = 85000, line discount 5% = 4250, bulk discount 2.5% = 2019, total discount 6269, VAT on 78731 = 16544
  // DEV-HOUR: 5 * 9500 = 47500, discount 5% = 2375, no bulk discount (qty<10), VAT on 45125 = 9476
  // Total discount: 6269 + 2375 = 8644, Total VAT: 16544 + 9476 = 26020
