test('invoiceTotals with real invoice from createInvoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(invoiceResult.value);
  // C-001 is gold tier, so lines get 5% discount
  // DES-HOUR: 10 * 8500 = 85000, line discount 5% = 4250, bulk discount 2.5% = 2019, total discount 6269, VAT on 78731 = 16544
  // DEV-HOUR: 5 * 9500 = 47500, discount 5% = 2375, no bulk discount (qty<10), VAT on 45125 = 9476
  // Total discount: 6269 + 2375 = 8644, Total VAT: 16544 + 9476 = 26020
  // Total: 132500 - 8644 + 26020 = 149876
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 8644);
  assert.equal(totals.vat, 26020);
  assert.equal(totals.total, 149876);
});

