      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 }, // bulk discount 2500, VAT on 97500 = 20475
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 9 }, // bulk discount 2500, VAT on 97500 = 8775
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }, // bulk discount 2500, VAT 0
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 300000
  // discount: 2500 + 2500 + 2500 = 7500
  // vat: 20475 + 8775 + 0 = 29250
  // total: 300000 - 7500 + 29250 = 321750
  assert.equal(totals.subtotal, 300000);
  assert.equal(totals.discount, 7500);
  assert.equal(totals.vat, 29250);
  assert.equal(totals.total, 321750);
});

test('invoiceTotals with discount and VAT together', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 5, vatRate: 21 }, // 100000 - 5000 = 95000, VAT 19950
      { qty: 50, unitPrice: 1000, discountPercent: 10, vatRate: 9 }, // 50000 - 5000 = 45000, VAT 4050
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 150000
  // discount: 10000
  // vat: 19950 + 4050 = 24000
  // total: 150000 - 10000 + 24000 = 164000
  assert.equal(totals.subtotal, 150000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.vat, 24000);
  assert.equal(totals.total, 164000);
});

