    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 12.5, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 5 * 1000 = 5000
  // discount: 5000 * 12.5 / 100 = 625 (no bulk discount since qty < 10)
  // vat: 0
  // total: 5000 - 625 + 0 = 4375
  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 625);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 4375);
});

