    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 10, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 5 * 1000 = 5000
  // discount: 5000 * 10 / 100 = 500 (no bulk discount since qty < 10)
  // vat: 0 (no VAT)
  // total: 5000 - 500 + 0 = 4500
