      { qty: 8, unitPrice: 1000, discountPercent: 20, vatRate: 0 }, // 8000 - 1600 = 6400
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 5000 + 8000 = 13000
  // discount: 500 + 1600 = 2100 (no bulk discounts since both qty < 10)
  // vat: 0
  // total: 13000 - 2100 + 0 = 10900
  assert.equal(totals.subtotal, 13000);
  assert.equal(totals.discount, 2100);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 10900);
});

test('invoiceTotals handles decimal discounts', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 12.5, vatRate: 0 }],
  };
