test('invoiceTotals with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 }, // 5000, VAT 21% = 1050
      { qty: 8, unitPrice: 1000, discountPercent: 0, vatRate: 9 }, // 8000, VAT 9% = 720
