});

test('invoiceTotals multiple lines with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }, // bulk discount: 250
      { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 }, // no bulk discount
      { qty: 15, unitPrice: 1000, discountPercent: 0, vatRate: 0 }, // bulk discount: 375
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 10000 + 9000 + 15000 = 34000
  // discount: 250 + 0 + 375 = 625
  assert.equal(totals.subtotal, 34000);
  assert.equal(totals.discount, 625);
  assert.equal(totals.total, 33375); // 34000 - 625
});

test('invoiceTotals bulk discount with VAT', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // baseTotal: 10000
  // bulk discount: 10000 * 2.5% = 250
  // amount after discount: 10000 - 250 = 9750
  // vat: 9750 * 21% = 2047.5 = 2048
  // total: 10000 - 250 + 2048 = 11798
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 2048);
  assert.equal(totals.total, 11798);
});

test('invoiceTotals bulk discount with line and tier discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // baseTotal: 10000
  // line discount: 10000 * 10% = 1000
  // bulk discount: (10000 - 1000) * 2.5% = 9000 * 2.5% = 225
  // total discount: 1000 + 225 = 1225
  // amount after discount: 10000 - 1225 = 8775
  // vat: 8775 * 21% = 1842.75 = 1843
  // total: 10000 - 1225 + 1843 = 10618
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1225);
  assert.equal(totals.vat, 1843);
  assert.equal(totals.total, 10618);
});

test('invoiceTotals bulk discount boundary (qty = 10 vs qty = 9)', () => {
  const invoice10 = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const invoice9 = {
    lines: [{ qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };

  const totals10 = invoiceTotals(invoice10);
  const totals9 = invoiceTotals(invoice9);

  // qty=10 should have discount, qty=9 should not
  assert.equal(totals10.discount, 250); // bulk discount applied
  assert.equal(totals9.discount, 0); // no bulk discount
  assert.equal(totals10.total, 9750);
  assert.equal(totals9.total, 9000);
});

test('invoiceTotals bulk discount with large quantities', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
