  // bulk discount: 100000 * 2.5% = 2500
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 2500);
  assert.equal(totals.total, 97500);
});

test('invoiceTotals bulk discount returns integer cents', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 333, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.ok(Number.isInteger(totals.discount));
  assert.ok(Number.isInteger(totals.total));
});

