test('invoiceTotals calculates discount for single line', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 100 * 1000 = 100000
  // line discount: 100000 * 10% = 10000
  // bulk discount: (100000 - 10000) * 2.5% = 2250
  // total discount: 10000 + 2250 = 12250
  // total: 100000 - 12250 + 0 = 87750
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 12250);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 87750);
});

test('invoiceTotals calculates discount for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 0 }, // line discount 10000, bulk discount 2250
      { qty: 50, unitPrice: 1000, discountPercent: 20, vatRate: 0 }, // line discount 10000, bulk discount 1000
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 100000 + 50000 = 150000
  // line 1: 10000 + 2250 = 12250, line 2: 10000 + 1000 = 11000
  // discount: 12250 + 11000 = 23250
  // vat: 0
  // total: 150000 - 23250 + 0 = 126750
  assert.equal(totals.subtotal, 150000);
  assert.equal(totals.discount, 23250);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 126750);
});

test('invoiceTotals handles decimal discounts', () => {
