test('invoiceTotals with mixed tier discounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 }, // 85000, 5% discount = 4250, bulk discount 2019, VAT on 78731 = 16544
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }, // 47500, explicit 0%, no bulk, VAT 21% = 9975
    ],
  });

  const totals = invoiceTotals(invoiceResult.value);
  // subtotal: 85000 + 47500 = 132500
  // discount: 4250 + 2019 + 0 = 6269
  // vat: 16544 + 9975 = 26519
  // total: 132500 - 6269 + 26519 = 152750
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 6269);
  assert.equal(totals.vat, 26519);
  assert.equal(totals.total, 152750);
});

test('invoiceTotals calculates VAT for single line', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 100000
  // bulk discount: 100000 * 2.5% = 2500
  // vat: 97500 * 21% = 20475
  // total: 100000 - 2500 + 20475 = 117975
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 2500);
  assert.equal(totals.vat, 20475);
  assert.equal(totals.total, 117975);
});

