  // subtotal: 100000
  // line discount: 10000, bulk discount: 2250, total discount: 12250
  // after discount: 87750
  // vat: 87750 * 21% = 18428
  // total: 100000 - 12250 + 18428 = 106178
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 12250);
  assert.equal(totals.vat, 18428);
  assert.equal(totals.total, 106178);
});

test('invoiceTotals with mixed VAT rates', () => {
